/* MyUniMentor admin panel (/admin). Only accounts in the ADMINS list (admin claim) can read anything; Firestore rules enforce it.
Loaded only on /admin. */
const ROOT = document.getElementById('adm');
const CFG = window.MUM_ACCOUNT || {};
const FB_VER = '12.11.0';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const $ = s => ROOT.querySelector(s), $$ = s => [...ROOT.querySelectorAll(s)];
const link = k => { const a = document.querySelector('.acct-links a[data-k="' + k + '"]'); return a ? a.getAttribute('href') : '#'; };
const STREAMS = { pcm: 'Science (PCM)', pcb: 'Science (PCB)', pcmb: 'Science (PCMB)', comm: 'Commerce with Maths', com: 'Commerce without Maths', hum: 'Humanities (Arts)', und: 'Not decided yet' };
const CLASSES = ['Class 9', 'Class 10', 'Class 11', 'Class 12', 'Gap year / dropper'];
const RSTAT = { requested: 'Requested', booked: 'Booked', done: 'Completed', cancelled: 'Cancelled' };
const toDate = t => t && t.toDate ? t.toDate() : t && t.seconds ? new Date(t.seconds * 1000) : t ? new Date(t) : null;
const fmt = (t, time) => { const d = toDate(t); return d ? d.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) + (time ? ', ' + d.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' }) : '') : '—'; };
const ago = t => { const d = toDate(t); return d ? (Date.now() - d) / 864e5 : 1e9; };
let fb = null, S = { users: [], requests: [], ann: [], archive: [], links: [], sentToday: 0, exams: [] }, TAB = 'overview', Q = '', ROLE = 'all', RFILTER = 'open';
async function loadFb() {
const base = 'https://www.gstatic.com/firebasejs/' + FB_VER + '/';
const [app, auth, fs] = await Promise.all([import(base + 'firebase-app.js'), import(base + 'firebase-auth.js'), import(base + 'firebase-firestore.js')]);
const a = app.initializeApp(CFG.firebase);
fb = { auth: auth.getAuth(a), A: auth, db: fs.getFirestore(a), F: fs };
}
function shell(h) { ROOT.innerHTML = h; ROOT.classList.remove('is-loading'); }
function gate(title, text, btn) { shell(`<div class="acct-card"><h2>${title}</h2><p class="acct-sub">${text}</p>${btn || ''}</div>`); }
async function load() {
const F = fb.F, all = async (col, ...q) => (await F.getDocs(q.length ? F.query(F.collection(fb.db, col), ...q) : F.collection(fb.db, col))).docs.map(d => Object.assign({ id: d.id }, d.data()));
const today = new Date(Date.now() + 5.5 * 36e5).toISOString().slice(0, 10);
const [users, requests, ann, archive, links, stat] = await Promise.all([all('users'), all('requests'), all('announcements'), all('archive').catch(() => []), all('links'), F.getDoc(F.doc(fb.db, 'stats', 'mail-' + today)).catch(() => null)]);
Object.assign(S, { users: users.map(u => Object.assign(u, { uid: u.id })), requests, ann, archive, links, sentToday: stat && stat.exists() ? stat.data().sent || 0 : 0 });
const byTime = (a, b) => (toDate(b.created) || 0) - (toDate(a.created) || 0);
S.users.sort(byTime); S.requests.sort(byTime); S.ann.sort(byTime); S.archive.sort((a, b) => (toDate(b.deletedAt) || 0) - (toDate(a.deletedAt) || 0));
}
function render() {
const open = S.requests.filter(r => r.status === 'requested').length, drafts = S.ann.filter(a => a.status === 'draft').length;
const tabs = [['overview', 'Overview'], ['people', `People <i>${S.users.length}</i>`], ['requests', `Counselling${open ? ` <i class="hot">${open}</i>` : ''}`],
['ann', `Announcements${drafts ? ` <i class="hot">${drafts}</i>` : ''}`], ['deleted', `Deleted <i>${S.archive.length}</i>`]];
shell(`<div class="adm">
<header class="adm-top"><div><p class="acct-k">MyUniMentor admin</p><h2>Students and parents</h2></div>
<div class="adm-top-btns"><button type="button" class="btn btn-outline btn-small adm-refresh">Refresh</button><a class="btn btn-outline btn-small" href="${link('account')}">My account</a></div></header>
<nav class="adm-tabs" role="tablist">${tabs.map(([k, t]) => `<button type="button" role="tab" data-t="${k}" aria-selected="${TAB === k}">${t}</button>`).join('')}</nav>
<div class="adm-body">${({ overview, people, requests: reqs, ann: annTab, deleted })[TAB]()}</div></div>`);
$$('.adm-tabs button').forEach(b => b.addEventListener('click', () => { TAB = b.dataset.t; render(); }));
$('.adm-refresh').addEventListener('click', async () => { $('.adm-refresh').textContent = 'Loading…'; await load(); render(); });
({ overview: () => {}, people: wirePeople, requests: wireReqs, ann: wireAnn, deleted: () => {} })[TAB]();
}
function bars(rows) {
const max = Math.max(1, ...rows.map(r => r[1]));
return rows.length ? `<ul class="adm-bars">${rows.map(([k, n]) => `<li><span>${esc(k)}</span><b style="--w:${Math.round(n / max * 100)}%"><i></i></b><em>${n}</em></li>`).join('')}</ul>` : '<p class="acct-muted">Nothing yet.</p>';
}
function count(list, f) { const m = {}; list.forEach(x => [].concat(f(x) || []).forEach(k => { if (k) m[k] = (m[k] || 0) + 1; })); return Object.entries(m).sort((a, b) => b[1] - a[1]); }
function overview() {
const st = S.users.filter(u => u.role === 'student'), pa = S.users.filter(u => u.role === 'parent');
const exName = id => (S.exams.find(e => e.id === id) || {}).exam || id;
const tile = (k, v, s) => `<div class="adm-tile"><span>${k}</span><b>${v}</b><small>${s}</small></div>`;
return `<div class="adm-tiles">${tile('Students', st.length, `${st.filter(u => ago(u.created) < 7).length} joined this week`)}${tile('Parents', pa.length, `${S.links.filter(l => l.status === 'accepted').length} linked to a child`)}
${tile('Open counselling', S.requests.filter(r => r.status === 'requested').length, `${S.requests.filter(r => r.status === 'booked').length} booked`)}${tile('Emails today', S.sentToday, 'of about 300 a day on Brevo free')}</div>
<div class="adm-grid">
<section class="acct-box"><h3>Students by class</h3>${bars(CLASSES.map(c => [c, st.filter(u => u.cls === c).length]).filter(r => r[1]))}</section>
<section class="acct-box"><h3>Students by stream</h3>${bars(count(st, u => STREAMS[u.stream]))}</section>
<section class="acct-box"><h3>Most followed exams</h3>${bars(count(st, u => (u.exams || []).map(exName)).slice(0, 8))}</section>
<section class="acct-box"><h3>Courses they’re interested in</h3>${bars(count(st, u => u.targets).slice(0, 8))}</section>
<section class="acct-box"><h3>Top cities</h3>${bars(count(S.users, u => (u.city || '').trim().replace(/\b\w/g, c => c.toUpperCase())).slice(0, 8))}</section>
<section class="acct-box"><h3>Latest sign-ups</h3><ul class="adm-mini">${S.users.slice(0, 6).map(u => `<li><b>${esc(u.name)}</b><span>${u.role === 'parent' ? 'Parent' : esc(u.cls || '')} · ${fmt(u.created)}</span></li>`).join('') || '<li>None yet.</li>'}</ul></section>
</div>`;
}
function peopleRows() {
const q = Q.trim().toLowerCase();
return S.users.filter(u => (ROLE === 'all' || u.role === ROLE) && (!q || [u.name, u.email, u.whatsapp, u.city, u.school].join(' ').toLowerCase().includes(q)));
}
function people() {
const rows = peopleRows(), name = uid => (S.users.find(u => u.uid === uid) || {}).name;
return `<div class="adm-bar"><input type="search" class="adm-search" placeholder="Search name, email, phone, city or school" value="${esc(Q)}" aria-label="Search people">
<select class="adm-role" aria-label="Show"><option value="all">Everyone</option><option value="student"${ROLE === 'student' ? ' selected' : ''}>Students</option><option value="parent"${ROLE === 'parent' ? ' selected' : ''}>Parents</option></select>
<button type="button" class="btn btn-outline btn-small adm-csv">Download CSV</button></div>
<p class="acct-muted">${rows.length} of ${S.users.length}</p>
<div class="adm-table-wrap"><table class="adm-table"><thead><tr><th>Name</th><th>Email</th><th>WhatsApp</th><th>Class and stream</th><th>City</th><th>Family</th><th>Joined</th><th></th></tr></thead><tbody>
${rows.map(u => { const kids = S.users.filter(s => (s.parents || []).includes(u.uid)).map(s => s.name);
return `<tr><td><b>${esc(u.name)}</b><small class="adm-role-pill r-${esc(u.role)}">${u.role === 'parent' ? 'Parent' : 'Student'}</small></td><td><a href="mailto:${esc(u.email)}">${esc(u.email)}</a></td>
<td>${u.whatsapp ? `<a href="https://wa.me/91${esc(u.whatsapp)}" target="_blank" rel="noopener">+91 ${esc(u.whatsapp)}</a>` : '—'}</td>
<td>${u.role === 'student' ? `${esc(u.cls)}<small>${esc(STREAMS[u.stream] || '')}</small>` : '—'}</td><td>${esc(u.city)}${u.school ? `<small>${esc(u.school)}</small>` : ''}</td>
<td>${u.role === 'student' ? ((u.parentEmails || []).map(esc).join('<br>') || '—') : (kids.map(esc).join('<br>') || '<small>Not linked</small>')}</td><td>${fmt(u.created)}</td>
<td><button type="button" class="acct-link adm-del" data-uid="${esc(u.uid)}">Delete</button></td></tr>`; }).join('') || '<tr><td colspan="8">No one matches.</td></tr>'}
</tbody></table></div>`;
}
function wirePeople() {
const s = $('.adm-search'); s.addEventListener('input', () => { Q = s.value; const pos = s.selectionStart; render(); const n = $('.adm-search'); n.focus(); n.setSelectionRange(pos, pos); });
$('.adm-role').addEventListener('change', e => { ROLE = e.target.value; render(); });
$('.adm-csv').addEventListener('click', () => {
const cols = ['name', 'role', 'email', 'whatsapp', 'cls', 'stream', 'city', 'school', 'targets', 'exams', 'parentEmails', 'created'];
const cell = v => '"' + String(Array.isArray(v) ? v.join('; ') : v && v.toDate ? fmt(v, true) : v == null ? '' : v).replace(/"/g, '""') + '"';
const csv = [cols.join(',')].concat(peopleRows().map(u => cols.map(c => cell(c === 'stream' ? STREAMS[u[c]] || u[c] : u[c])).join(','))).join('\n');
const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['﻿' + csv], { type: 'text/csv' })); a.download = 'myunimentor-accounts-' + new Date().toISOString().slice(0, 10) + '.csv'; a.click();
});
$$('.adm-del').forEach(b => b.addEventListener('click', async () => {
const u = S.users.find(x => x.uid === b.dataset.uid);
if (!confirm(`Delete ${u.name} (${u.email})?\n\nTheir dashboard and emails stop. A copy is kept under Deleted, and their counselling requests stay.`)) return;
b.textContent = 'Deleting…'; const F = fb.F;
try {
const copy = Object.assign({}, u, { deletedAt: F.serverTimestamp(), deletedBy: 'admin' }); delete copy.id;
await F.setDoc(F.doc(fb.db, 'archive', u.uid + '-' + Date.now()), copy);
if (u.whatsapp) await F.deleteDoc(F.doc(fb.db, 'phones', u.whatsapp)).catch(() => {});
await F.deleteDoc(F.doc(fb.db, 'users', u.uid));
await load(); render();
} catch (x) { alert('Could not delete: ' + x.message); b.textContent = 'Delete'; }
}));
}
function reqs() {
const list = S.requests.filter(r => RFILTER === 'all' || (RFILTER === 'open' ? ['requested', 'booked'].includes(r.status) : r.status === RFILTER));
return `<div class="adm-bar"><select class="adm-rf" aria-label="Show">${[['open', 'Open (requested and booked)'], ['requested', 'Requested'], ['booked', 'Booked'], ['done', 'Completed'], ['cancelled', 'Cancelled'], ['all', 'All']].map(([k, t]) => `<option value="${k}"${RFILTER === k ? ' selected' : ''}>${t}</option>`).join('')}</select>
<p class="acct-muted">Students see the status, time and notes on their dashboard.</p></div>
<div class="adm-reqs">${list.map(r => `<form class="acct-box adm-req" data-id="${esc(r.id)}">
<div class="adm-req-head"><div><b>${esc(r.studentName)}</b><span class="acct-pill p-${esc(r.status)}">${RSTAT[r.status] || esc(r.status)}</span>
<p class="acct-muted">${esc(r.cls)}${r.stream ? ' · ' + esc(STREAMS[r.stream] || r.stream) : ''} · asked ${fmt(r.created, true)}${r.byName && r.byName !== r.studentName ? ` · by parent ${esc(r.byName)}` : ''}</p></div>
<div class="adm-contact">${r.phone ? `<a class="btn btn-cyan btn-small" href="https://wa.me/91${esc(r.phone)}" target="_blank" rel="noopener">WhatsApp</a><a class="btn btn-outline btn-small" href="tel:+91${esc(r.phone)}">Call</a>` : ''}<a class="btn btn-outline btn-small" href="mailto:${esc(r.email)}">Email</a></div></div>
<blockquote>${esc(r.topic) || '<i>No topic written</i>'}<small>Best time: ${esc(r.slot || 'Any time')}</small></blockquote>
<div class="adm-req-edit"><label>Status<select name="status">${Object.entries(RSTAT).map(([k, t]) => `<option value="${k}"${r.status === k ? ' selected' : ''}>${t}</option>`).join('')}</select></label>
<label><span>Session time <span class="opt">(shown to the student)</span></span><input name="when" value="${esc(r.when)}" placeholder="e.g. Sat 28 Nov, 5 pm"></label>
<label class="adm-wide"><span>Notes for the student <span class="opt">(shown on their dashboard)</span></span><textarea name="notes" rows="3" placeholder="Summary, next steps, colleges to look at…">${esc(r.notes)}</textarea></label></div>
<div class="acct-actions"><span class="adm-saved" hidden>Saved</span><button class="btn btn-cyan btn-small" type="submit">Save</button></div></form>`).join('') || '<p class="acct-muted">No requests here.</p>'}</div>`;
}
function wireReqs() {
$('.adm-rf').addEventListener('change', e => { RFILTER = e.target.value; render(); });
$$('.adm-req').forEach(f => f.addEventListener('submit', async e => {
e.preventDefault(); const b = f.querySelector('button[type=submit]'); b.disabled = true;
const up = { status: f.status.value, when: f.when.value.trim(), notes: f.notes.value.trim(), updated: fb.F.serverTimestamp() };
try { await fb.F.updateDoc(fb.F.doc(fb.db, 'requests', f.dataset.id), up); Object.assign(S.requests.find(r => r.id === f.dataset.id), up); const s = f.querySelector('.adm-saved'); s.hidden = false; setTimeout(() => { s.hidden = true; }, 1800); }
catch (x) { alert('Could not save: ' + x.message); }
b.disabled = false;
}));
}
const on = (u, k) => (u.notify || {})[k] !== false;
function audience(a) {
const aud = a.audience || {}, streams = aud.streams || [], classes = aud.classes || [];
return S.users.filter(u => {
if (aud.role && aud.role !== 'all' && u.role !== aud.role) return false;
if (!['instant', 'reminders', 'digest'].some(k => on(u, k))) return false;
const look = u.role === 'student' ? [u] : S.users.filter(s => (s.parents || []).includes(u.uid));
if (streams.length && !look.some(s => streams.includes(s.stream))) return false;
if (classes.length && !look.some(s => classes.includes(s.cls))) return false;
return true;
});
}
const ASTAT = { draft: 'Draft', approved: 'Sending', sent: 'Sent' };
function annForm(a) {
a = a || { audience: { role: 'all' } }; const aud = a.audience || {};
const chips = (name, obj, sel) => Object.entries(obj).map(([k, v]) => `<label><input type="checkbox" name="${name}" value="${esc(k)}"${(sel || []).includes(k) ? ' checked' : ''}><span>${esc(v)}</span></label>`).join('');
return `<form class="acct-box acct-form adm-ann-form" data-id="${esc(a.id || '')}"><h3>${a.id ? 'Edit draft' : 'New announcement'}</h3>
<label>Subject<input name="subject" maxlength="90" required value="${esc(a.subject)}" placeholder="e.g. Free Career Summit at your school"></label>
<label>Message<textarea name="body" rows="6" required placeholder="Write it like a short note. Leave an empty line between paragraphs.">${esc(a.body)}</textarea></label>
<div class="acct-grid"><label><span>Button text <span class="opt">(optional)</span></span><input name="cta_label" value="${esc(a.cta_label)}" placeholder="e.g. See the details"></label>
<label><span>Button link <span class="opt">(optional)</span></span><input name="cta_url" type="url" value="${esc(a.cta_url)}" placeholder="https://myunimentor.in/…"></label></div>
<fieldset class="acct-targets"><legend>Send to</legend><div class="acct-chips">${[['all', 'Everyone'], ['student', 'Students only'], ['parent', 'Parents only']].map(([k, t]) => `<label><input type="radio" name="role" value="${k}"${(aud.role || 'all') === k ? ' checked' : ''}><span>${t}</span></label>`).join('')}</div></fieldset>
<fieldset class="acct-targets"><legend>Only these streams <span class="opt">(leave empty for all)</span></legend><div class="acct-chips">${chips('streams', STREAMS, aud.streams)}</div></fieldset>
<fieldset class="acct-targets"><legend>Only these classes <span class="opt">(leave empty for all)</span></legend><div class="acct-chips">${chips('classes', Object.fromEntries(CLASSES.map(c => [c, c])), aud.classes)}</div></fieldset>
<p class="adm-count"></p><div class="acct-actions adm-ann-btns"><button type="button" class="acct-link adm-ann-cancel">Cancel</button><button class="btn btn-outline btn-small" type="submit">Save draft</button></div></form>`;
}
function annTab() {
return `<div class="adm-bar"><button type="button" class="btn btn-cyan btn-small adm-ann-new">New announcement</button>
<p class="acct-muted">Nothing is sent until you press “Approve and send”. Emails go out within the hour. New guides on the site appear here as drafts for you to approve.</p></div>
<div class="adm-ann-slot"></div>
<div class="adm-anns">${S.ann.map(a => `<article class="acct-box adm-ann" data-id="${esc(a.id)}"><div class="adm-req-head"><div><b>${esc(a.subject)}</b><span class="acct-pill p-${a.status === 'sent' ? 'done' : a.status === 'approved' ? 'booked' : 'requested'}">${ASTAT[a.status] || esc(a.status)}</span>${a.auto ? '<span class="acct-pill">Auto draft</span>' : ''}
<p class="acct-muted">${a.status === 'sent' ? `Sent to ${a.sentCount || 0} people · ${fmt(a.sentAt, true)}` : a.status === 'approved' ? `Approved · ${a.sentCount || 0} sent so far` : `Will reach about ${audience(a).length} people`} · ${audDesc(a)}</p></div></div>
<div class="adm-ann-body">${esc(a.body).replace(/\n/g, '<br>')}${a.cta_url ? `<p><a href="${esc(a.cta_url)}" target="_blank" rel="noopener">${esc(a.cta_label || 'Find out more')}</a></p>` : ''}</div>
${a.status === 'draft' ? `<div class="acct-actions adm-ann-btns"><button type="button" class="acct-link adm-ann-rm">Delete</button><button type="button" class="btn btn-outline btn-small adm-ann-edit">Edit</button><button type="button" class="btn btn-cyan btn-small adm-ann-go">Approve and send</button></div>` : ''}</article>`).join('') || '<p class="acct-muted">No announcements yet.</p>'}</div>`;
}
function audDesc(a) {
const aud = a.audience || {}, parts = [aud.role === 'student' ? 'Students' : aud.role === 'parent' ? 'Parents' : 'Everyone'];
if ((aud.streams || []).length) parts.push(aud.streams.map(s => STREAMS[s] || s).join(', '));
if ((aud.classes || []).length) parts.push(aud.classes.join(', '));
return esc(parts.join(' · '));
}
function wireAnn() {
const slot = $('.adm-ann-slot');
const open = a => {
slot.innerHTML = annForm(a); const f = slot.querySelector('form'), cnt = f.querySelector('.adm-count');
const read = () => ({ subject: f.subject.value.trim(), body: f.body.value.trim(), cta_label: f.cta_label.value.trim(), cta_url: f.cta_url.value.trim(),
audience: { role: f.role.value, streams: [...f.querySelectorAll('[name=streams]:checked')].map(x => x.value), classes: [...f.querySelectorAll('[name=classes]:checked')].map(x => x.value) } });
const upd = () => { cnt.textContent = `Will reach about ${audience(read()).length} people (anyone who turned off every email is left out).`; };
f.addEventListener('change', upd); upd();
f.querySelector('.adm-ann-cancel').addEventListener('click', () => { slot.innerHTML = ''; });
f.addEventListener('submit', async e => {
e.preventDefault(); const d = read();
if (!d.subject || !d.body) { alert('Add a subject and a message.'); return; }
if (d.cta_url && !/^https:\/\//.test(d.cta_url)) { alert('The button link must start with https://'); return; }
const F = fb.F;
try {
if (f.dataset.id) await F.updateDoc(F.doc(fb.db, 'announcements', f.dataset.id), d);
else await F.addDoc(F.collection(fb.db, 'announcements'), Object.assign(d, { status: 'draft', created: F.serverTimestamp() }));
await load(); render();
} catch (x) { alert('Could not save: ' + x.message); }
});
f.subject.focus();
};
$('.adm-ann-new').addEventListener('click', () => open());
$$('.adm-ann').forEach(card => {
const a = S.ann.find(x => x.id === card.dataset.id), F = fb.F, ref = F.doc(fb.db, 'announcements', a.id);
const ed = card.querySelector('.adm-ann-edit'), go = card.querySelector('.adm-ann-go'), rm = card.querySelector('.adm-ann-rm');
if (ed) ed.addEventListener('click', () => { open(a); slot.scrollIntoView({ behavior: 'smooth' }); });
if (rm) rm.addEventListener('click', async () => { if (confirm('Delete this draft?')) { await F.deleteDoc(ref); await load(); render(); } });
if (go) go.addEventListener('click', async () => {
const n = audience(a).length;
if (!confirm(`Send “${a.subject}” to about ${n} people?\n\nIt goes out within the hour and can’t be taken back.`)) return;
await F.updateDoc(ref, { status: 'approved', approvedAt: F.serverTimestamp() }); await load(); render();
});
});
}
function deleted() {
return `<p class="acct-muted">Accounts deleted by the student or parent (with an emailed code) or by an admin. Their profile is kept here; their counselling requests stay under Counselling.</p>
<div class="adm-table-wrap"><table class="adm-table"><thead><tr><th>Name</th><th>Email</th><th>WhatsApp</th><th>Class and stream</th><th>City</th><th>Joined</th><th>Deleted</th></tr></thead><tbody>
${S.archive.map(u => `<tr><td><b>${esc(u.name)}</b><small class="adm-role-pill r-${esc(u.role)}">${u.role === 'parent' ? 'Parent' : 'Student'}</small></td><td>${esc(u.email)}</td><td>${u.whatsapp ? '+91 ' + esc(u.whatsapp) : '—'}</td>
<td>${esc(u.cls || '—')}<small>${esc(STREAMS[u.stream] || '')}</small></td><td>${esc(u.city)}</td><td>${fmt(u.created)}</td><td>${fmt(u.deletedAt, true)}<small>${u.deletedBy === 'admin' ? 'by an admin' : 'by themselves'}</small></td></tr>`).join('') || '<tr><td colspan="7">No deleted accounts.</td></tr>'}
</tbody></table></div>`;
}
(async function boot() {
try { S.exams = await (await fetch(link('exams'))).json(); } catch (e) {}
if (location.hash === '#demo') return demo();
if (!CFG.firebase || !CFG.firebase.apiKey) return gate('Not set up', 'Firebase settings are missing.');
try { await loadFb(); } catch (e) { return gate('Could not load', 'Check your internet connection and refresh.'); }
fb.A.onAuthStateChanged(fb.auth, async u => {
if (!u) return gate('Log in first', 'Log in with your MyUniMentor staff email, then come back to this page.', `<a class="btn btn-cyan" href="${link('account')}">Log in</a>`);
const t = await u.getIdTokenResult(true);
if (t.claims.admin !== true) return gate('Staff only', `You’re logged in as ${esc(t.claims.em || u.email || '')}, which isn’t on the admin list.`);
try { await load(); render(); } catch (e) { gate('Could not load data', esc(e.message) + '. Check that the latest Firestore rules are published.'); }
});
})();
